<?php
// Regression checks for the selective MitFrame badcea04..c6e7e124 port.
// Only ordinary, legitimate inputs are used: the checks confirm that the
// ported code keeps normal behaviour while using its new escaping paths.
define('IN_DISCUZ', true);
define('IN_API', true);
define('TIMESTAMP', 1700000000);
define('DISCUZ_ROOT', dirname(__DIR__, 2).'/');
set_error_handler(function($severity, $message, $file, $line) {
	throw new ErrorException($message, 0, $severity, $file, $line);
});

function check_port($condition, $message) {
	if(!$condition) throw new RuntimeException($message);
}

$core = file_get_contents(DISCUZ_ROOT.'source/function/function_core.php');
foreach(['dintval', 'stripsearchkey'] as $name) {
	$start = strpos($core, "function $name(");
	$end = strpos($core, "\nfunction ", $start + 1);
	eval(substr($core, $start, $end - $start));
}

class DB {
	public static $calls = [];
	static function table($name) { return 'pre_'.$name; }
	static function field($name, $value) { return '`'.$name.'`=\''.addslashes((string)$value).'\''; }
	static function limit($start, $limit) { return ''; }
	static function delete($table, $condition) { self::$calls[] = ['delete', $table, $condition]; }
	static function result_first($sql, $args = []) { self::$calls[] = ['result_first', $sql, $args]; return 0; }
	static function fetch_all($sql, $args = [], $key = '') { self::$calls[] = ['fetch_all', $sql, $args]; return []; }
	static function last() { return end(self::$calls); }
}
class discuz_table {
	public $data = [];
	public $methods = [];
	protected $_table;
	protected $_pk;
	protected $_pre_cache_key;
	protected $_cache_ttl;
	protected $_allowmem = false;
	public function __construct() {}
	public function __get($name) {
		if($name === 'table') return $this->_table;
		throw new Exception('Undefined property '.$name);
	}
}

// Ad embed codes generated by AdminCP use ids such as custom_3.
function loadcore() {}
function getgpc($name) { return $_GET[$name] ?? null; }
function adshow($parameter, $allowRegister = true) { $GLOBALS['adparams'][] = $parameter; return 'ad'; }
function dheader($header) {}
foreach(['custom_3' => 'custom_3', 'headerbanner/1' => 'headerbanner/1'] as $input => $expected) {
	$_GET = ['adid' => $input];
	$adparams = [];
	ob_start();
	include DISCUZ_ROOT.'api/javascript/advertisement.php';
	ob_end_clean();
	check_port($adparams === [$expected], 'Valid ad id was not passed through: '.$input);
}
$_GET = ['adid' => ['custom_3']];
$adparams = [];
ob_start();
include DISCUZ_ROOT.'api/javascript/advertisement.php';
ob_end_clean();
check_port($adparams === [''], 'Non-string ad id was not normalised');

// Announcement cache must keep rows and expose groups as arrays for the index.
class table_forum_announcement {
	static function t() { return new self; }
	function fetch_all_by_date($time) {
		return [
			3 => ['id' => 3, 'type' => 0, 'groups' => '1,2', 'subject' => 'Rules'],
			5 => ['id' => 5, 'type' => 1, 'groups' => '', 'subject' => 'Link', 'message' => 'https://example.test/'],
		];
	}
}
function savecache($name, $value) { $GLOBALS['savedcache'][$name] = $value; }
require DISCUZ_ROOT.'source/function/cache/cache_announcements.php';
build_cache_announcements();
$announcements = $savedcache['announcements'];
check_port(array_keys($announcements) === [3, 5], 'Announcement keys changed');
check_port($announcements[3]['groups'] === ['1', '2'] && $announcements[5]['groups'] === [], 'Announcement groups were not split');
check_port(in_array('2', $announcements[3]['groups']) && $announcements[5]['message'] === 'https://example.test/', 'Announcement row content changed');

// Thread profile group deletion uses a quoted field condition.
require DISCUZ_ROOT.'source/class/table/table_forum_threadprofile_group.php';
table_forum_threadprofile_group::t()->delete_by_tpid(7);
check_port(DB::last() === ['delete', 'forum_threadprofile_group', "`tpid`='7'"], 'Thread profile group deletion condition changed');

// Attachment manager numeric bounds remain applied as integers.
require DISCUZ_ROOT.'source/class/table/table_forum_attachment.php';
table_forum_attachment::t()->fetch_all_for_manage(0, '', 0, '', '', '2048', '4096', '3', '9', 0, 1);
$sql = DB::last()[1];
foreach(["a.filesize>'2048'", "a.filesize<'4096'", "ai.downloads>'3'", "ai.downloads<'9'"] as $expected) {
	check_port(str_contains($sql, $expected), 'Attachment filter missing: '.$expected);
}

// Portal comment moderation filters build without notices and keep their values.
require DISCUZ_ROOT.'source/class/table/table_common_moderate.php';
table_common_moderate::t()->fetch_all_for_portalcomment('aid', 'portal_article_title', '0', '4', 'Zoë', '86400', 1, "don't stop");
$sql = DB::last()[1];
check_port(str_contains($sql, "a.catid='4'"), 'Moderation category filter missing');
check_port(str_contains($sql, "a.username='Zoë'"), 'Moderation username filter changed');
check_port(str_contains($sql, "a.dateline>'".(TIMESTAMP - 86400)."'"), 'Moderation date filter changed');
check_port(str_contains($sql, "c.message LIKE '%don\\'t stop%'"), 'Moderation keyword was not quoted for SQL');
check_port(str_contains($sql, " AND c.idtype='aid'") && str_contains($sql, "m.status='0'"), 'Moderation type/status condition changed');
table_common_moderate::t()->fetch_all_for_portalcomment('aid', 'portal_article_title', 0, 0, '', 'all', 1, '');
check_port(!str_contains(DB::last()[1], 'a.catid') && !str_contains(DB::last()[1], 'a.dateline'), 'Empty moderation filters were applied');

