require DISCUZ_ROOT.'source/class/table/table_forum_postcomment.php';
table_forum_postcomment::t()->count_by_search(null, null, null, null, null, null, 'v1.2{3}');
check_port(str_contains(DB::last()[2][1], "comment REGEXP 'v1\\\\.2.{0,3}'"), 'Comment REGEXP literal was not escaped like post search');

echo "Upstream 20261120 ad id, announcement cache, profile group, attachment, moderation and wildcard search regressions passed\n";
